    33→
    34→/**
    35→ *
    36→ */
    37→public class DimFilterUtils
    38→{
    39→  static final byte SELECTOR_CACHE_ID = 0x0;
    40→  static final byte AND_CACHE_ID = 0x1;
    41→  static final byte OR_CACHE_ID = 0x2;
    42→  static final byte NOT_CACHE_ID = 0x3;
    43→  static final byte EXTRACTION_CACHE_ID = 0x4;
    44→  static final byte REGEX_CACHE_ID = 0x5;
    45→  static final byte SEARCH_QUERY_TYPE_ID = 0x6;
    46→  static final byte JAVASCRIPT_CACHE_ID = 0x7;
    47→  static final byte SPATIAL_CACHE_ID = 0x8;
    48→  static final byte IN_CACHE_ID = 0x9;
    49→  static final byte BOUND_CACHE_ID = 0xA;
    50→  static final byte INTERVAL_CACHE_ID = 0xB;
    51→  static final byte LIKE_CACHE_ID = 0xC;
    52→  static final byte COLUMN_COMPARISON_CACHE_ID = 0xD;
    53→  static final byte EXPRESSION_CACHE_ID = 0xE;
    54→  static final byte TRUE_CACHE_ID = 0xF;
    55→  static final byte FALSE_CACHE_ID = 0x11;
    56→  public static final byte BLOOM_DIM_FILTER_CACHE_ID = 0x10;
    57→
    58→  public static final byte STRING_SEPARATOR = (byte) 0xFF;
    59→
    60→  static byte[] computeCacheKey(byte cacheIdKey, List<DimFilter> filters)
    61→  {
    62→    if (filters.size() == 1) {
    63→      return filters.get(0).getCacheKey();
    64→    }
    65→
    66→    byte[][] cacheKeys = new byte[filters.size()][];
    67→    int totalSize = 0;
    68→    int index = 0;
    69→    for (DimFilter field : filters) {
    70→      cacheKeys[index] = field.getCacheKey();
    71→      totalSize += cacheKeys[index].length;
    72→      ++index;
    73→    }
    74→
    75→    ByteBuffer retVal = ByteBuffer.allocate(1 + totalSize);
    76→    retVal.put(cacheIdKey);
    77→    for (byte[] cacheKey : cacheKeys) {
    78→      retVal.put(cacheKey);
    79→    }
    80→    return retVal.array();
    81→  }
