   251→  /**
   252→   * Removes all occurrences of the given char from the given string. This method is an optimal version of
   253→   * {@link String#replace(CharSequence, CharSequence) s.replace("c", "")}.
   254→   */
   255→  public static String removeChar(String s, char c)
   256→  {
