   294→  /**
   295→   * Replaces all occurrences of the given target substring in the given string with the given replacement string. This
   296→   * method is an optimal version of {@link String#replace(CharSequence, CharSequence) s.replace(target, replacement)}.
   297→   */
   298→  public static String replace(String s, String target, String replacement)
   299→  {
   300→    // String.replace() is suboptimal in JDK8, but is fixed in JDK9+. When the minimal JDK version supported by Druid is
   301→    // JDK9+, the implementation of this method should be replaced with simple delegation to String.replace(). However,
   302→    // the method should still be prohibited to use in all other places except this method body, because it's easy to
   303→    // suboptimally call String.replace("a", "b"), String.replace("a", ""), String.replace("a", "abc"), which have
   304→    // better alternatives String.replace('a', 'b'), removeChar() and replaceChar() respectively.
   305→    int pos = s.indexOf(target);
   306→    if (pos < 0) {
   307→      return s;
   308→    }
   309→    int sLength = s.length();
   310→    int targetLength = target.length();
   311→    // This is needed to work correctly with empty target string and mimic String.replace() behavior
   312→    int searchSkip = Math.max(targetLength, 1);
   313→    StringBuilder sb = new StringBuilder(sLength - targetLength + replacement.length());
   314→    int prevPos = 0;
   315→    do {
   316→      sb.append(s, prevPos, pos);
   317→      sb.append(replacement);
   318→      prevPos = pos + targetLength;
   319→      // Break from the loop if the target is empty
   320→      if (pos == sLength) {
   321→        break;
   322→      }
   323→      pos = s.indexOf(target, pos + searchSkip);
   324→    } while (pos > 0);
   325→    sb.append(s, prevPos, sLength);
   326→    return sb.toString();
   327→  }
