   423→  /**
   424→   * Returns a string whose value is the concatenation of the
   425→   * string {@code s} repeated {@code count} times.
   426→   * <p>
   427→   * If count or length is zero then the empty string is returned.
   428→   * <p>
   429→   * This method may be used to create space padding for
   430→   * formatting text or zero padding for formatting numbers.
   431→   *
   432→   * @param count number of times to repeat
   433→   *
   434→   * @return A string composed of this string repeated
   435→   * {@code count} times or the empty string if count
   436→   * or length is zero.
   437→   *
   438→   * @throws IllegalArgumentException if the {@code count} is negative.
   439→   * @link https://bugs.openjdk.java.net/browse/JDK-8197594
   440→   */
   441→  public static String repeat(String s, int count)
   442→  {
   443→    if (count < 0) {
   444→      throw new IllegalArgumentException("count is negative, " + count);
   445→    }
   446→    if (count == 1) {
   447→      return s;
   448→    }
   449→    byte[] value = s.getBytes(StandardCharsets.UTF_8);
   450→    final int len = value.length;
   451→    if (len == 0 || count == 0) {
   452→      return "";
   453→    }
   454→    if (len == 1) {
   455→      final byte[] single = new byte[count];
   456→      Arrays.fill(single, value[0]);
   457→      return new String(single, StandardCharsets.UTF_8);
   458→    }
   459→    if (Integer.MAX_VALUE / count < len) {
   460→      throw new RuntimeException("The produced string is too large.");
   461→    }
   462→    final int limit = len * count;
   463→    final byte[] multiple = new byte[limit];
   464→    System.arraycopy(value, 0, multiple, 0, len);
   465→    int copied = len;
   466→    for (; copied < limit - copied; copied <<= 1) {
   467→      System.arraycopy(multiple, 0, multiple, copied, copied);
   468→    }
   469→    System.arraycopy(multiple, 0, multiple, copied, limit - copied);
   470→    return new String(multiple, StandardCharsets.UTF_8);
   471→  }
