   473→  /**
   474→   * Returns the string left-padded with the string pad to a length of len characters.
   475→   * If str is longer than len, the return value is shortened to len characters.
   476→   * This function is migrated from flink's scala function with minor refactor
   477→   * https://github.com/apache/flink/blob/master/flink-table/flink-table-planner/src/main/scala/org/apache/flink/table/runtime/functions/ScalarFunctions.scala
   478→   * - Modified to handle empty pad string.
   479→   * - Padding of negative length return an empty string.
   480→   *
   481→   * @param base The base string to be padded
   482→   * @param len  The length of padded string
   483→   * @param pad  The pad string
   484→   *
   485→   * @return the string left-padded with pad to a length of len or null if the pad is empty or the len is less than 0.
   486→   */
   487→  @Nonnull
   488→  public static String lpad(@Nonnull String base, int len, @Nonnull String pad)
   489→  {
   490→    if (len <= 0) {
   491→      return "";
   492→    }
   493→
   494→    // The length of the padding needed
   495→    int pos = Math.max(len - base.length(), 0);
   496→
   497→    // short-circuit if there is no pad and we need to add a padding
   498→    if (pos > 0 && pad.isEmpty()) {
   499→      return base;
   500→    }
   501→
   502→    char[] data = new char[len];
   503→
   504→    // Copy the padding
   505→    for (int i = 0; i < pos; i += pad.length()) {
   506→      for (int j = 0; j < pad.length() && j < pos - i; j++) {
   507→        data[i + j] = pad.charAt(j);
   508→      }
   509→    }
   510→
   511→    // Copy the base
   512→    for (int i = 0; pos + i < len && i < base.length(); i++) {
   513→      data[pos + i] = base.charAt(i);
   514→    }
   515→
   516→    return new String(data);
   517→  }
