   519→  /**
   520→   * Returns the string right-padded with the string pad to a length of len characters.
   521→   * If str is longer than len, the return value is shortened to len characters.
   522→   * This function is migrated from flink's scala function with minor refactor
   523→   * https://github.com/apache/flink/blob/master/flink-table/flink-table-planner/src/main/scala/org/apache/flink/table/runtime/functions/ScalarFunctions.scala
   524→   * - Modified to handle empty pad string.
   525→   * - Modified to only copy the pad string if needed (this implementation mimics lpad).
   526→   * - Padding of negative length return an empty string.
   527→   *
   528→   * @param base The base string to be padded
   529→   * @param len  The length of padded string
   530→   * @param pad  The pad string
   531→   *
   532→   * @return the string right-padded with pad to a length of len or null if the pad is empty or the len is less than 0.
   533→   */
   534→  @Nonnull
   535→  public static String rpad(@Nonnull String base, int len, @Nonnull String pad)
   536→  {
   537→    if (len <= 0) {
   538→      return "";
   539→    }
   540→
   541→    // The length of the padding needed
   542→    int paddingLen = Math.max(len - base.length(), 0);
   543→
   544→    // short-circuit if there is no pad and we need to add a padding
   545→    if (paddingLen > 0 && pad.isEmpty()) {
   546→      return base;
   547→    }
   548→
   549→    char[] data = new char[len];
   550→
   551→
   552→    // Copy the padding
   553→    for (int i = len - paddingLen; i < len; i += pad.length()) {
   554→      for (int j = 0; j < pad.length() && i + j < data.length; j++) {
   555→        data[i + j] = pad.charAt(j);
   556→      }
   557→    }
   558→
   559→    // Copy the base
   560→    for (int i = 0; i < len && i < base.length(); i++) {
   561→      data[i] = base.charAt(i);
   562→    }
   563→
   564→    return new String(data);
   565→  }
